const { slug, meta, blocks, titles, source_lang: src } = $('Assemble Multilingual Blocks').item.json;
const q = JSON.stringify;
const fm = (t, s) => `+++\ndate = ${q(meta.date)}\nlastmod = ${q(meta.date)}\ndraft = false\ntitle = ${q(t)}\nsummary = ${q(s)}\n[params]\n  author = ${q(meta.author)}\n+++\n\n`;
const emit = (b, lang) => {
  if (b.kind === 'title' || b.kind === 'text') return b[lang] || '';
  if (b.kind === 'youtube') return `{{< youtube ${b.media.youtube_id} >}}`;
  const m = b.media;
  return m.kind === 'video' ? `{{< video src="${m.bundle_filename}" >}}` : `![${m.alt || ''}](${m.bundle_filename})`;
};
const body = (lang) => blocks.map((b) => emit(b, lang)).filter(Boolean).join('\n\n');
const firstPara = (bd) => {
  const out = [];
  for (const line of bd.split('\n')) {
    const t = line.trim();
    if (!out.length && !t) continue;
    if (out.length && (!t || t[0] === '#' || t === '---' || t === '***' || t === '___')) break;
    out.push(line);
  }
  return out.join(' ').trim();
};
const DISC = {
  en: '*This blog post has been automatically translated by a Large Language Model.',
  de: '*Dieser Blogbeitrag wurde automatisch von einem Large Language Model uebersetzt.',
  es: '*Esta publicacion de blog ha sido traducida automaticamente por un Large Language Model.',
  fr: '*Cet article de blog a ete traduit automatiquement par un Large Language Model.',
  it: '*Questo post del blog e stato tradotto automaticamente da un Large Language Model.',
  arrr: "*Arrr, this here blog post be rewritten in the tongue o' pirates by a Large Language Model, ye scallywag!*",
};
return [{
  json: {
    indexFiles: Object.keys(titles).map((code) => {
      const b = body(code).replace(/[\s\r\n]+$/, '');
      const full = code === src ? b : `${b}\n\n---\n\n${DISC[code] || ''}`;
      const summary = code === src ? (meta.summary || firstPara(full)) : firstPara(full);
      return { repo_path: `content/posts/${slug}/index.${code}.md`, content: fm(titles[code] || meta.title, summary) + full + '\n' };
    }),
  },
}];

const prep = $('Prepare Blocks').item.json;
const parseTr = (j) => {
  let t = j?.output?.[0]?.content?.[0]?.text ?? j;
  if (typeof t === 'string') t = JSON.parse(t);
  return t.translations || [];
};
const blocks = prep.blocks.map((b) => ({ ...b }));
const titles = { [prep.source_lang]: prep.title };
for (const tr of [...parseTr($('Natural Language Translation').item.json), ...parseTr($('Pirate Speak Generator').item.json)]) {
  const code = tr.lang_code;
  if (!code || code === prep.source_lang) continue;
  titles[code] = code === 'arrr' ? prep.title : (tr.title || prep.title);
  for (const { index: i, text } of tr.items || []) {
    if (blocks[i] && (blocks[i].kind === 'title' || blocks[i].kind === 'text')) blocks[i][code] = text ?? '';
  }
}
return [{ json: { slug: prep.slug, meta: prep.meta, source_lang: prep.source_lang, blocks, titles } }];

const src = $('Publish Webhook').item.json.body ?? $('Publish Webhook').item.json;
const anchor = (src.site_media || []).find((e) =>
  e.repo_path && e.sftp_path && e.sftp_path.endsWith(e.repo_path)
);
if (!anchor) throw new Error('cannot derive Hugo staging root from site_media');
const root = anchor.sftp_path.slice(0, -anchor.repo_path.length).replace(/\/$/, '');
return $('Generate Hugo Index MDs').first().json.indexFiles.map((f) => ({
  json: {
    sftp_path: `${root}/${f.repo_path}`,
    content: f.content,
  },
}));
